#[doc = r" Converts a parse tree to JSON format for visualization."]
#[doc = r" Returns a JSON string with nodes and edges arrays."]
pub fn to_json(node: ParseTree<'_>) -> String {
    let mut nodes = Vec::new();
    let mut edges = Vec::new();
    let mut next_id = 0u32;
    build_json_graph(node, &mut nodes, &mut edges, &mut next_id);
    let result = serde_json :: json ! ({ "nodes" : nodes , "edges" : edges });
    result.to_string()
}
fn build_json_graph(
    node: ParseTree<'_>,
    nodes: &mut Vec<serde_json::Value>,
    edges: &mut Vec<serde_json::Value>,
    next_id: &mut u32,
) -> u32 {
    let my_id = *next_id;
    *next_id += 1;
    let span = node.span();
    let kind = match node {
        ParseTree::Token(_) => "Token",
        _ => "Nonterminal",
    };
    nodes . push (serde_json :: json ! ({ "id" : my_id , "kind" : kind , "label" : node . display_name () , "start" : span . left_extent , "end" : span . right_extent })) ;
    for child in node.children() {
        let child_id = build_json_graph(child, nodes, edges, next_id);
        edges.push(serde_json :: json ! ({ "src" : my_id , "dest" : child_id }));
    }
    my_id
}
